write('/methodology/', layout({ route: '/methodology/', title: 'Operational Diagnostic Methodology | Phull Insights', description: 'A visible Map–Measure–Diagnose–Rebuild method for operational evidence, root cause and practical action.', eyebrow: 'Peer route · Methodology', h1: 'Root cause before recommendation. Evidence before confidence.', lead: 'A practical method for keeping observed facts, calculations, assumptions, estimates and recommendations separate.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Methodology', path: '/methodology/' }], body: `<section class="content-section section-border"><div class="container"><div class="step-grid"><article><span>01</span><h2>Map</h2><p>Agree the journey boundary, events, owners and decision in scope.</p></article><article><span>02</span><h2>Measure</h2><p>Build the baseline and show evidence quality beside performance.</p></article><article><span>03</span><h2>Diagnose</h2><p>Test patterns, alternatives and where variability enters the system.</p></article><article><span>04</span><h2>Rebuild</h2><p>Prioritise the first intervention, owner and verification points.</p></article></div></div></section><section class="content-section section-border"><div class="container"><p class="eyebrow">Evidence ladder</p><div class="route-grid"><article class="route-card"><h3>Observed</h3><p>Present in or directly traceable to the source record.</p></article><article class="route-card"><h3>Calculated</h3><p>Derived through a documented, repeatable formula.</p></article><article class="route-card"><h3>Assumed</h3><p>A business input reviewed and approved by the accountable owner.</p></article><article class="route-card"><h3>Estimated</h3><p>An opportunity range combining evidence with stated assumptions.</p></article><article class="route-card"><h3>Recommended</h3><p>A proposed intervention subject to operational judgement.</p></article><article class="route-card"><h3>Stop</h3><p>The correct conclusion when the evidence cannot justify the next step.</p></article></div></div></section>${primaryCta('A useful diagnostic narrows the decision before it widens the programme.')}` }));

write('/about/', layout({ route: '/about/', title: 'About Pupsi Phull | Phull Insights', description: 'About Pupsi Phull, the operator-led perspective behind Phull Insights, and the origin of the brand.', eyebrow: 'About Phull Insights', h1: 'Operator accountability, applied to advisory work.', lead: 'Phull Insights brings operational reality, structured diagnosis and accountable human judgement to complex decisions.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'About', path: '/about/' }], schemas: [person], body: `<section class="content-section section-border"><div class="container split-layout"><div class="rich-copy"><p class="eyebrow">Pupsi Phull · Founder</p><h2>Depth beyond the headline measure.</h2><p>The founder profile spans regulated MedTech, distribution, supply chain, operations leadership and transformation. The advisory standard is simple: make the evidence visible, keep unlike responsibilities separate and recommend only what the operating context can support.</p><p>Founder-led delivery means the person framing the diagnostic remains accountable for the reasoning, caveats and executive synthesis.</p><h2>Selected credentials</h2><ul><li>Executive MBA, Cranfield School of Management</li><li>Postgraduate Certificate in Sustainability, Cranfield University, 2026</li><li>BSc, De Montfort University</li><li>PRINCE2 Practitioner</li><li>Six Sigma</li></ul></div><aside class="side-panel"><h3>Approved profile scope</h3><p><strong>£230m revenue scope</strong></p><p><strong>£100m P&amp;L accountability</strong></p><p>These responsibilities are deliberately presented as separate proof points.</p><a class="text-link" href="/executive-leadership/">Executive leadership profile →</a><a class="text-link" href="https://uk.linkedin.com/in/pupsi" rel="me external">View recommendations on LinkedIn →</a></aside></div></section><section class="content-section brand-origin section-border"><div class="container split-layout"><div><p class="eyebrow">Why “Phull”?</p><h2>Full insight. Real depth.</h2><p class="lead-copy">Phull is a family name that sounds like “full”, and that is the standard we set: full insight, with no surface-level shortcuts. In Punjabi, phull also means flower, a reminder that real understanding opens up in layers. Phull Insights exists to look beneath the numbers, reach the cause, and turn what we find into decisions that hold up in practice.</p><p class="review-note">Owner-approved wording: retain the Punjabi meaning and transliteration. No additional language or historical derivation is claimed.</p></div><div class="dictionary-card"><p><strong>Phull Insights</strong> /fʊl ˈɪn.saɪts/</p><p><em>proper noun</em></p><h3>Brand origin</h3><p>The name joins three readings: the family name, the promise of full insights and the image of a flower opening to reveal what lies within.</p><ol><li>A whole-picture understanding reached by looking beyond surface reports and metrics.</li><li>Analysis that makes clear what is happening, why and what to do next.</li><li>The unfolding of understanding as each layer reveals the next.</li><li>An advisory identity grounded in operational reality.</li></ol><p><strong>Usage note:</strong> The sound signals completeness, the meaning signals clarity and the flower signals growth.</p></div></div></section>${primaryCta('Bring an operating problem, not a predetermined solution.')}` }));

write('/executive-leadership/', layout({ route: '/executive-leadership/', title: 'Executive Operations Leadership Profile | Phull Insights', description: 'Executive operations, supply chain and transformation leadership profile for Director, COO and VP-level mandates.', eyebrow: 'Recruiter route · Executive leadership', h1: 'Executive operations leadership for complex, multi-site environments.', lead: 'A recruiter-focused profile of level, functional breadth, sectors and scale—kept separate from consultancy sales content.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Executive leadership', path: '/executive-leadership/' }], schemas: [person], body: `<section class="content-section section-border"><div class="container"><div class="profile-grid"><article><p class="card-tag">Target level</p><h2>Director, COO and VP-level mandates</h2><p>Roles where operational judgement, transformation discipline and cross-functional accountability need to work together.</p></article><article><p class="card-tag">Functional breadth</p><h2>Operations · Supply chain · Transformation</h2><p>Operating-model leadership, multi-site performance, programme recovery and technology-enabled change.</p></article><article><p class="card-tag">Sectors</p><h2>Regulated MedTech · Distribution · Complex operations</h2><p>Environments where service, cost, risk and governance cannot be assessed in isolation.</p></article><article><p class="card-tag">Scale</p><h2>Responsibilities shown separately</h2><p>£230m revenue scope and £100m P&amp;L accountability. The figures are not combined.</p></article></div></div></section><section class="content-section section-border"><div class="container split-layout"><div class="rich-copy"><p class="eyebrow">Leadership pattern</p><h2>Strategy that survives contact with delivery.</h2><ul><li>Translate executive intent into an operating rhythm and accountable decisions.</li><li>Distinguish structural problems from imported performance.</li><li>Connect programme governance to service, cost, people and risk.</li><li>Build evidence that boards and operating teams can challenge.</li><li>Hand over routines that do not depend on one individual.</li></ul><p><a class="text-link" href="https://uk.linkedin.com/in/pupsi" rel="me external">Read third-party recommendations on LinkedIn →</a></p></div><aside class="side-panel"><h3>Recruiter next step</h3><p>Share the mandate, level, sector and success profile. No CV link is planned at present.</p><a class="btn btn-primary" data-event="recruiter_contact" href="mailto:hello@phullinsights.com?subject=Executive%20mandate%20discussion">Discuss an executive mandate</a></aside></div></section>` }));

const insightTopics = [
  { slug: 'delivery-confirmed-otif', title: 'Delivery-confirmed OTIF: where the measure stops', summary: 'A method-only case for testing promise logic, measurement boundaries and the customer event that defines success.', state: 'published' },
  { slug: 'inventory-service-protected', title: 'Reducing inventory while protecting service', summary: 'A method-only case for segmenting stock, demand, constraints and availability before changing policy.', state: 'published' },
  { slug: 'cold-chain-sla-redesign', title: 'Cold-chain SLA redesign', summary: 'A method-only case for aligning contract measures, product thresholds, dwell time and accountable review.', state: 'published' },
  { slug: 'regulated-medtech-baseline', title: 'A MedTech KPI baseline that functions can accept', summary: 'Quality, finance and operations need one traceable baseline before corrective action.', state: 'held' },
  { slug: 'network-restructuring-decisions', title: 'Separating local and imported network cost', summary: 'A network decision method that distinguishes site economics, routing and leadership conditions.', state: 'held' },
  { slug: 'improvement-verification', title: '30-day and 90-day improvement verification', summary: 'A method for checking whether change holds after the workshop and handover.', state: 'held' },
  { slug: 'edi-billing-exceptions', title: 'Removing EDI billing exceptions upstream', summary: 'Trace exceptions before invoicing and make tolerance decisions explicit.', state: 'held' },
  { slug: 'supplier-performance-promise-logic', title: 'Supplier performance and promise logic', summary: 'Separate supplier variability from internal commitment and escalation rules.', state: 'held' },
  { slug: 'operational-controls-queues', title: 'When an operational control becomes a queue', summary: 'Protect required controls while testing avoidable waiting around the hand-off.', state: 'held' },
  { slug: 'diagnostic-before-system', title: 'The diagnostic that says do not build', summary: 'Four tests before technology investment: access, novelty, actionability and repeatability.', state: 'held' },
];

write('/insights/', layout({ route: '/insights/', title: 'Operations Case Studies and Insights | Phull Insights', description: 'Anonymised operations and supply chain cases covering OTIF, inventory, cold chain, MedTech, networks and improvement.', eyebrow: 'Peer route · Insights hub', h1: 'Operating questions, methods and evidence boundaries.', lead: 'Ten priority cases are approved for anonymised use. The first three have complete case pages; seven are queued for drafting without company names or unverified metrics.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Insights', path: '/insights/' }], body: `<section class="content-section section-border"><div class="container"><div class="insight-grid">${insightTopics.map((topic, index) => `<article class="insight-card"><div class="insight-meta"><span>${String(index + 1).padStart(2, '0')}</span><span>${topic.state === 'published' ? 'Anonymised case' : 'Anonymised case queued'}</span></div><h2>${topic.title}</h2><p>${topic.summary}</p>${topic.state === 'published' ? `<a class="text-link" href="/insights/${topic.slug}/">Read case <span aria-hidden="true">→</span></a>` : '<p class="held-note">Company names are excluded. The page and any metrics await source review.</p>'}</article>`).join('')}</div></div></section><section class="content-section section-border"><div class="container split-layout"><div><p class="eyebrow">Editorial rule</p><h2>Anonymise identity. Verify every number.</h2><p class="lead-copy">Owner approval permits case narratives without company names. Metrics remain unpublished until the source, period, baseline and wording have a recorded evidence decision.</p></div><aside class="side-panel"><h3>Every published case includes</h3><ul><li>Challenge and context</li><li>Diagnosis and rebuild</li><li>Evidence decision</li><li>Questions for the reader</li><li>Related service and case links</li><li>Author and preview date</li></ul></aside></div></section>` }));

const casePages = {
  'delivery-confirmed-otif': { title: 'Delivery-Confirmed OTIF: A Method-Only Case | Phull Insights', h1: 'Delivery-confirmed OTIF: where does the measure stop?', description: 'A method-only case for diagnosing OTIF boundaries, promise logic, exceptions and customer delivery confirmation.', sector: 'Distribution and multi-site operations', challenge: 'A headline OTIF score can remain stable while customer promises change repeatedly, orders require manual intervention and the internal measure stops before confirmed delivery.', diagnosis: 'Reconstruct requirement, commitment, promise change, shipment, delivery confirmation and exception handling as one event sequence. Then test which date and event the organisation uses as success.', rebuild: 'Agree a service definition, preserve the original and changed promises, show exceptions before failure and assign ownership for each decision point.', questions: ['Does the measure stop at despatch or confirmed delivery?', 'How many promise changes occur before a line scores on time?', 'Which exceptions were imported and which were created internally?', 'What management effort is invisible in the score?'], service: ['/services/supply-chain-consultancy/', 'Supply Chain Consultancy'], related: ['/insights/inventory-service-protected/', 'Inventory with service protected'] },
  'inventory-service-protected': { title: 'Inventory Reduction With Service Protected | Phull Insights', h1: 'How can inventory fall without collapsing service?', description: 'A method-only case for segmenting inventory, service, constraints and availability before changing stock policy.', sector: 'Supply chain and inventory management', challenge: 'Aggregate stock can rise while customer availability deteriorates. A broad reduction target can remove the wrong inventory and increase expediting.', diagnosis: 'Segment demand, lead time, lifecycle, constraint, customer promise and stock state. Distinguish physical stock from operationally available stock and trace where uncertainty enters.', rebuild: 'Change policy by segment, test the service effect, make exceptions visible and verify the result at 30 and 90 days before scaling.', questions: ['Which inventory is unavailable despite being physically present?', 'Where is buffer compensating for unreliable lead time or data?', 'Which service definition must be protected?', 'What evidence would stop the reduction?'], service: ['/services/supply-chain-consultancy/', 'Supply Chain Consultancy'], related: ['/insights/delivery-confirmed-otif/', 'Delivery-confirmed OTIF'] },
  'cold-chain-sla-redesign': { title: 'Cold-Chain SLA Redesign: A Method-Only Case | Phull Insights', h1: 'Why can a green SLA still produce quarantined stock?', description: 'A method-only case for aligning cold-chain service measures, product thresholds, dwell time and human review.', sector: 'Temperature-controlled and regulated logistics', challenge: 'A consignment can meet a contracted time-and-temperature measure while still failing the product-specific operating threshold used by the receiving organisation.', diagnosis: 'Map contracted milestones, product thresholds, packaging configuration, hub dwell, release dependencies and the customer decision that determines usable stock.', rebuild: 'Align the measurement boundary to the product journey, set accountable dwell thresholds and retain qualified human judgement for disposition and regulatory decisions.', questions: ['Which threshold determines customer usability?', 'Where does dwell accumulate?', 'Do the contract and product profiles use the same event boundary?', 'Who is accountable for reviewing an excursion?'], service: ['/services/medtech-supply-chain/', 'MedTech Supply Chain'], related: ['/insights/delivery-confirmed-otif/', 'Delivery-confirmed OTIF'] },
};

for (const [slug, entry] of Object.entries(casePages)) {
  const route = `/insights/${slug}/`;
  const article = { '@context': 'https://schema.org', '@type': 'Article', headline: entry.h1, description: entry.description, datePublished: '2026-09-20', dateModified: '2026-09-20', author: { '@type': 'Person', name: 'Pupsi Phull' }, publisher: { '@type': 'Organization', name: 'Phull Insights' }, mainEntityOfPage: `${productionBase}${route}` };
  write(route, layout({ route, title: entry.title, description: entry.description, eyebrow: `Anonymised case · ${entry.sector}`, h1: entry.h1, lead: entry.description, pageType: 'article', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Insights', path: '/insights/' }, { name: entry.h1, path: route }], schemas: [article], body: `<article class="content-section section-border"><div class="container article-layout"><div class="article-meta"><span>Anonymised case</span><span>Author: Pupsi Phull</span><span>${buildLabel}</span></div><div class="review-note"><strong>Evidence decision:</strong> owner approval permits anonymised case use. Company names are excluded; metrics remain omitted until source, period and baseline are verified.</div><div class="rich-copy"><h2>Challenge</h2><p>${entry.challenge}</p><h2>Diagnosis</h2><p>${entry.diagnosis}</p><h2>Rebuild</h2><p>${entry.rebuild}</p><h2>Questions for the reader</h2><ul>${entry.questions.map((question) => `<li>${question}</li>`).join('')}</ul></div><div class="related-panel"><a href="${entry.service[0]}">${entry.service[1]} <span aria-hidden="true">→</span></a><a href="${entry.related[0]}">Related case: ${entry.related[1]} <span aria-hidden="true">→</span></a><a href="/insights/">All Insights <span aria-hidden="true">→</span></a><a href="/contact/">Discuss the operating question <span aria-hidden="true">→</span></a></div></div></article>` }));
}

write('/trust/', layout({ route: '/trust/', title: 'Working With Phull Insights | Trust, Data and Human Review', description: 'How Phull Insights approaches scoping, confidentiality, data minimisation, human review, AI use, retention and subcontractors.', eyebrow: 'Trust and working principles', h1: 'A useful diagnosis must be proportionate, explainable and safe to challenge.', lead: 'This preview describes the intended operating principles. Contractual controls and provider details remain unpublished until documentary evidence and legal review are complete.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Trust', path: '/trust/' }], body: `<section class="content-section section-border"><div class="container"><div class="step-grid trust-steps"><article><span>01</span><h2>Scope</h2><p>Agree the decision question, roles, exclusions and minimum evidence boundary.</p></article><article><span>02</span><h2>Control</h2><p>Confirm permitted data, access, providers, transfer method, retention and deletion before data moves.</p></article><article><span>03</span><h2>Review</h2><p>Keep calculations, caveats, assumptions and alternative explanations visible to accountable people.</p></article><article><span>04</span><h2>Close</h2><p>Agree handover, deletion evidence, unresolved risks and the owner of each next action.</p></article></div></div></section><section class="content-section section-border"><div class="container split-layout"><div class="rich-copy"><h2>Minimum necessary data</h2><p>Only operational evidence needed to answer the agreed question should be requested. Patient data, special-category personal data and confidential files are not required for the initial conversation and should not be sent.</p><h2>Human review and AI use</h2><p>Deterministic metrics and financial logic should remain documented and reconcilable. AI may assist with approved unstructured material or narrative drafting, but accountable human review remains part of every finding and recommendation.</p><h2>Client systems and subcontractors</h2><p>System access, processors, specialist support and subcontractors must be engagement-specific, approved and documented. This preview does not imply that any particular provider or control is already in place.</p><h2>Retention and deletion</h2><p>Use a documented, purpose-based schedule; review records regularly; delete or anonymise them when the purpose ends. Proposed web-enquiry periods are listed on the privacy page for owner and legal review.</p></div><aside class="side-panel"><h3>Current disclosure position</h3><ul><li>No insurance claim is published</li><li>No accreditation or formal certification is claimed</li><li>Standard contractual protections await approval</li><li>Subprocessors and data locations await provider selection</li><li>Third-party recommendations are referenced only through LinkedIn</li></ul></aside></div></section>` }));

write('/privacy/', layout({ route: '/privacy/', title: 'Privacy Outline | Phull Insights', description: 'Preview privacy outline for Phull Insights business enquiries, with confirmed controller wording and approved retention periods.', eyebrow: 'Privacy · Preview outline', h1: 'A narrow privacy foundation for business enquiries.', lead: 'This is a non-production outline. The controller wording and retention periods are owner-approved; the postal address, providers, data flows and approval date still require completion before publication.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Privacy outline', path: '/privacy/' }], body: `<section class="content-section section-border"><div class="container narrow rich-copy"><div class="review-note"><strong>Data controller:</strong> Pupsi Phull trading as Full Insight.<br><strong>Postal address:</strong> To be updated before production. No company, registered-office or jurisdiction statement is claimed.</div><h2>Information in scope</h2><p>A business enquiry may include a name, work contact details, organisation, role, selected route and the information supplied about an operational or executive mandate.</p><h2>Proposed purposes and lawful basis</h2><p>The intended purposes are to respond to an enquiry, assess fit, take steps requested before a contract and manage a legitimate business relationship. The final lawful-basis wording requires legal review against the actual form, analytics and providers.</p><h2>Data minimisation</h2><p>Do not send patient data, special-category personal data, confidential operational files or credentials through the initial enquiry route.</p><h2>Approved retention schedule</h2><ul><li>Client, recruiter and peer enquiries that do not progress: delete or anonymise 12 months after the last meaningful contact.</li><li>Analytics events, if enabled with valid consent: retain for no more than 14 months, then aggregate or delete.</li><li>Consent records: retain only as long as needed to demonstrate the active choice and handle withdrawal.</li><li>Contracts, invoices and engagement records: set a separate legally reviewed period based on actual tax, contractual and limitation requirements.</li></ul><p>These are approved working periods, not a claimed universal standard. Review them regularly and delete earlier when the purpose has ended.</p><h2>Cookies and analytics</h2><p>The preview uses local storage only to remember the colour-theme choice and does not run analytics. The production analytics platform remains open. If analytics is enabled, non-essential tracking must remain off until consent; Accept all, Reject all and Manage choices must be equally available; withdrawal must be possible; and Client, Recruiter and Peer route events must be recorded separately only after consent.</p><h2>Providers and transfers</h2><p>The hosted-form and spam-protection providers remain open. Hosting, email, form, analytics, data-location and international-transfer details will be inserted only after the selected services and settings are confirmed.</p><h2>Rights and complaints</h2><p>The production notice will explain access, correction, deletion, restriction, objection and complaint routes, including the UK Information Commissioner where applicable.</p><h2>Privacy contact</h2><p>Until the final notice is approved, privacy questions may be sent to <a href="mailto:hello@phullinsights.com?subject=Privacy%20question">hello@phullinsights.com</a>.</p></div></section>` }));

write('/journeyiq/', layout({ route: '/journeyiq/', title: 'JourneyIQ Operational Diagnostic Concept | Phull Insights', description: 'JourneyIQ is a bounded operational diagnostic concept showing inputs, outputs, data controls and accountable human review.', eyebrow: 'JourneyIQ · Prototype demonstrator', h1: 'JourneyIQ: an evidence-led operational diagnostic concept.', lead: 'JourneyIQ remains the working name for this preview. The owner plans to review and change the name in the next version; no broader product or trade-mark claim is made.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'JourneyIQ', path: '/journeyiq/' }], body: `<section class="content-section section-border"><div class="container split-layout"><div class="rich-copy"><div class="review-note"><strong>Naming status:</strong> keep temporarily. JourneyIQ remains visible in this preview and is scheduled for a naming decision in the next version.</div><h2>What the concept is</h2><p>A prototype for structuring a bounded operational question, tracing the available evidence and presenting a reviewable decision brief.</p><h2>Who it is for</h2><p>Operations and supply chain leaders who need to clarify a problem before committing to a large programme, system change or pilot.</p><h2>Inputs</h2><p>A named decision question, an accountable owner and the minimum approved evidence set. No patient data or confidential files are needed for an initial conversation.</p><h2>Outputs</h2><p>A traceable evidence map, visible assumptions, ranked diagnostic questions and a prioritised next-step brief. No automated decision or guaranteed outcome is implied.</p><h2>Human judgement and AI</h2><p>AI may assist with approved unstructured material, but accountable human review remains responsible for definitions, calculations, caveats and recommendations.</p></div><aside class="side-panel"><h3>Before any pilot</h3><ul><li>Next-version naming decision</li><li>Commercial scope and legal terms</li><li>Allowed dataset and minimum fields</li><li>Provider, access and retention controls</li><li>Named reviewer and success criteria</li><li>Deletion plan and incident responsibility</li></ul></aside></div></section>` }));

write('/contact/', layout({ route: '/contact/', title: 'Contact Phull Insights | Operations Advisory Enquiries', description: 'Choose a client, recruiter or peer enquiry route for Phull Insights. No operational data is needed for the first conversation.', eyebrow: 'Contact · Route-specific enquiries', h1: 'Start with the reason for the conversation.', lead: 'Choose the route that fits. All three routes are designed to reach Pupsi at hello@phullinsights.com and to be tracked separately. The preview form remains disabled until the hosted provider and spam controls are approved.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Contact', path: '/contact/' }], body: `<section class="content-section section-border"><div class="container contact-layout"><div class="contact-route-list"><article data-route="client"><p class="card-tag">Client</p><h2>Request a 30-minute Operational Diagnostic</h2><p>Share the operating symptom and the decision that is difficult to make. No operational files are needed.</p></article><article data-route="recruiter"><p class="card-tag">Recruiter</p><h2>Discuss an executive mandate</h2><p>Share the level, scope, sector and success profile for a confidential fit conversation.</p></article><article data-route="peer"><p class="card-tag">Peer</p><h2>Exchange methods or commentary</h2><p>Share a method, speaking topic or operating question worth exploring.</p></article></div><div class="form-panel"><form id="preview-contact-form" action="/contact/thank-you/" method="post"><fieldset><legend>Rich hosted-form specification</legend><label for="route">Enquiry route</label><select id="route" name="route" required><option value="client">Client</option><option value="recruiter">Recruiter</option><option value="peer">Peer or speaking</option></select><label for="name">Name</label><input id="name" name="name" autocomplete="name" required><label for="email">Work email</label><input id="email" name="email" type="email" autocomplete="email" required><label for="organisation">Organisation</label><input id="organisation" name="organisation" autocomplete="organization"><label for="role">Role or mandate</label><input id="role" name="role" autocomplete="organization-title"><label for="message">What decision or mandate do you want to discuss?</label><textarea id="message" name="message" rows="5" required></textarea><label class="consent-check"><input type="checkbox" name="privacy_acknowledgement" required> I understand this information will be used to respond to my enquiry.</label><p class="form-warning">Do not send patient data, special-category personal data, confidential files or operational extracts.</p><button class="btn btn-primary" type="submit">Preview form only</button><p class="form-status" id="form-status" role="status"></p></fieldset></form><p>Planned recipient for every route: <a data-event="email_click" href="mailto:hello@phullinsights.com">hello@phullinsights.com</a>. No response-time promise is made.</p></div></div></section>` }));

write('/contact/thank-you/', layout({ route: '/contact/thank-you/', title: 'Enquiry Received | Phull Insights', description: 'Preview acknowledgement page for a Phull Insights enquiry.', eyebrow: 'Preview acknowledgement', h1: 'Thank you.', lead: 'This route is ready for a future hosted form, but no submission reaches it in this preview.', breadcrumbs: [{ name: 'Home', path: '/' }, { name: 'Contact', path: '/contact/' }, { name: 'Thank you', path: '/contact/thank-you/' }], body: `<section class="content-section section-border"><div class="container narrow"><p>Your enquiry has been recorded. This acknowledgement deliberately makes no response-time promise.</p><p>The production form remains blocked until a hosted-form provider, privacy wording, spam protection and end-to-end delivery to hello@phullinsights.com are approved and tested.</p><a class="text-link" href="/contact/">Return to contact</a></div></section>` }));

const routes = ['/', '/services/', ...services.map((service) => `/services/${service.slug}/`), '/methodology/', '/about/', '/executive-leadership/', '/insights/', ...Object.keys(casePages).map((slug) => `/insights/${slug}/`), '/trust/', '/privacy/', '/journeyiq/', '/contact/', '/contact/thank-you/'];

fs.copyFileSync(path.resolve(__dirname, 'preview.css'), path.join(out, 'styles.css'));
fs.copyFileSync(path.resolve(__dirname, 'preview.js'), path.join(out, 'app.js'));
